if(!defined('VELTRION_RUNTIME_GUARD') && file_exists(__DIR__ . '/../bootstrap/guard.php')){ @include_once __DIR__ . '/../bootstrap/guard.php'; }
  class ContextCache { private string $cacheFile; public function __construct(string $cacheFile = '') { $base = realpath(__DIR__ . '/../../../../storage') ?: (getcwd() . '/storage'); if (!is_dir($base . '/cache')) { @mkdir($base . '/cache', 0777, true); } $this->cacheFile = $cacheFile ?: $base . '/cache/ai_context.json'; } public function get(): ?array { if (file_exists($this->cacheFile)) { $data = json_decode(file_get_contents($this->cacheFile) ?: '[]', true); return is_array($data) ? $data : null; } return null; } public function set(array $files): void { $payload = [ 'updated_at' => date('Y-m-d H:i:s'), 'file_count' => count($files), 'files' => $files ]; file_put_contents($this->cacheFile, json_encode($payload, JSON_PRETTY_PRINT)); } public function clear(): void { if (file_exists($this->cacheFile)) { @unlink($this->cacheFile); } } public function getStats(): array { $cached = $this->get(); if (!$cached) { return [ 'status' => 'Cache no generado', 'updated_at' => 'N/A', 'file_count' => 0 ]; } return [ 'status' => 'Activo', 'updated_at' => $cached['updated_at'] ?? 'Desconocido', 'file_count' => $cached['file_count'] ?? 0, 'cache_size_bytes' => file_exists($this->cacheFile) ? filesize($this->cacheFile) : 0 ]; } } 